require __DIR__.'/bootstrap.php';require_auth();if(!can('purchases.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$stmt=$db->prepare('INSERT INTO suppliers(supplier_code,name,phone,email,address) VALUES(?,?,?,?,?)');try{$stmt->execute([trim($_POST['supplier_code']),trim($_POST['name']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address'])]);audit($db,'create','supplier',(int)$db->lastInsertId());flash('success','Supplier saved. You can now enter their purchase invoice.');}catch(Throwable $e){flash('danger','Supplier code already exists or the information is invalid.');}redirect('suppliers.php');}
$rows=$db->query('SELECT * FROM suppliers WHERE status="active" ORDER BY name')->fetchAll();page_start('Suppliers','suppliers.php');?>
<div class="page-grid"><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Who supplies the stock?</span><h3><?=count($rows)?> suppliers</h3></div></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Supplier</th><th>Phone</th><th class="right">Amount we owe</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['supplier_code'])?></b><br><a class="row-edit" href="edit_record.php?type=supplier&id=<?=$r['id']?>">Edit</a></td><td><?=e($r['name'])?></td><td><?=e($r['phone']?:'—')?></td><td class="right"><b><?=money($r['outstanding'])?></b></td></tr><?php endforeach;?></tbody></table></div></section><aside class="panel"><div class="panel-head"><div><span class="eyebrow">One-time setup</span><h3>Add a supplier</h3></div></div><p class="plain-help">Use the code printed on your supplier records. The same code is used by Excel imports.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=csrf()?>"><label>Supplier code<input name="supplier_code" placeholder="Example: SUP-001" required></label><label>Phone<input name="phone" placeholder="Keep starting zero"></label><label class="full">Supplier name<input name="name" required></label><label class="full">Email<input type="email" name="email"></label><label class="full">Address<textarea name="address" rows="3"></textarea></label><button class="btn primary full">Save Supplier</button></form></aside></div><?php page_end();
